def canConvertString(s: str, t: str, k: int) -> bool:
    if len(s) != len(t):
        return False

    count = {}

    for i in range(len(s)):
        diff = (ord(t[i]) - ord(s[i])) % 26
        if diff == 0:
            continue

        if diff in count:
            count[diff] += 1
        else:
            count[diff] = 1

        # Calculate the minimum move number needed for this specific difference
        # If we have seen this difference before, we need to add 26 for each previous occurrence
        # because we can't reuse the same move number.
        needed_move = diff + 26 * (count[diff] - 1)

        if needed_move > k:
            return False

    return True
